function openZoho(event) {
  const url = "https://projects.zoho.in/"; // use your portal URL / data center

  try {
    if (Office.context.ui && Office.context.ui.openBrowserWindow) {
      Office.context.ui.openBrowserWindow(url);
    } else {
      window.open(url, "_blank");
    }
  } catch (e) {
    window.open(url, "_blank");
  }

  event.completed(); // tells Outlook the command has finished
}

Office.onReady(() => {});
Office.actions.associate("openZoho", openZoho);